(function () {
  "use strict";
  function post(msg) {
    try {
      window.parent.postMessage(msg, "*");
    } catch (err) {}
  }
  function applyMessage(msg) {
    var prev = document.getElementById("tk-transition-style");
    if (prev) prev.remove();
    var style = document.createElement("style");
    style.id = "tk-transition-style";
    style.textContent = msg.css;
    document.head.appendChild(style);
    var applied = false;
    function apply() {
      if (msg.kind === "theme") {
        document.documentElement.classList.toggle("dark");
      } else {
        document.documentElement.classList.toggle("tk-page-transition");
      }
      applied = true;
    }
    if (document.startViewTransition) {
      document.startViewTransition(apply);
    } else {
      apply();
    }
    setTimeout(function () {
      if (applied) post({ source: "transition-kit", type: "applied", kind: msg.kind });
    }, 50);
  }
  post({ source: "transition-kit", type: "ready" });
  window.addEventListener("message", function (event) {
    var msg = event.data;
    if (!msg || msg.source !== "transition-kit" || msg.type !== "trigger") return;
    applyMessage(msg);
  });
})();
